// Obtener datos del contexto
const promptData = $('Obtener Prompt de BD').first().json;
const agentOutput = $('Agente IA - DEMO').first().json;
const chatInput = $('When chat message received').first().json;

// Limpiar la respuesta (quitar el marcador)
let cleanOutput = agentOutput.output || '';
cleanOutput = cleanOutput.replace('[CONVERSACION_FINALIZADA]', '').trim();

// Intentar obtener el historial completo de la memoria del agente
let historialHTML = '';

try {
  // El agente guarda el historial en chatHistory
  const chatHistory = agentOutput.chatHistory || [];

  if (chatHistory && chatHistory.length > 0) {
    // Construir HTML del historial completo
    for (const msg of chatHistory) {
      if (msg.type === 'human' || msg.kwargs?.type === 'human' || msg.id?.includes('HumanMessage')) {
        const content = msg.content || msg.kwargs?.content || msg.text || '';
        historialHTML += `
<div style="background: linear-gradient(135deg, #1e40af, #3b82f6); color: white; padding: 12px 16px; border-radius: 12px; margin: 10px 0 10px 20%; text-align: right;">
  <strong>👤 Usuario:</strong> ${content}
</div>`;
      } else if (msg.type === 'ai' || msg.kwargs?.type === 'ai' || msg.id?.includes('AIMessage')) {
        const content = msg.content || msg.kwargs?.content || msg.text || '';
        historialHTML += `
<div style="background: white; border: 1px solid #e0e0e0; padding: 12px 16px; border-radius: 12px; margin: 10px 20% 10px 0;">
  <strong style="color: #06d6a0;">🤖 Asistente:</strong> ${content.replace('[CONVERSACION_FINALIZADA]', '').trim()}
</div>`;
      }
    }
  }
} catch (e) {
  console.log('Error accediendo al historial:', e.message);
}

// Si no pudimos obtener el historial de memoria, usar el mensaje actual
if (!historialHTML || historialHTML.trim() === '') {
  historialHTML = `
<div style="background: linear-gradient(135deg, #1e40af, #3b82f6); color: white; padding: 12px 16px; border-radius: 12px; margin: 10px 0 10px 20%; text-align: right;">
  <strong>👤 Usuario:</strong> ${chatInput.chatInput || 'N/A'}
</div>
<div style="background: white; border: 1px solid #e0e0e0; padding: 12px 16px; border-radius: 12px; margin: 10px 20% 10px 0;">
  <strong style="color: #06d6a0;">🤖 Asistente:</strong> ${cleanOutput}
</div>`;
}

return {
  client_email: promptData.data?.client_email || '',
  company_name: promptData.data?.company_name || 'Cliente',
  session_id: chatInput.sessionId || '',
  historial_html: historialHTML,
  clean_output: cleanOutput,
  output: cleanOutput,
  fecha: new Date().toLocaleDateString('es-CL', { 
    day: '2-digit', 
    month: '2-digit', 
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  })
};
